// Fehlermeldung für Telegram bauen (Klartext, ohne Markdown).
const j = $input.first().json;
const ex = j.execution || {};
const wf = j.workflow || {};
const err = ex.error || {};
const msg = String(err.message || 'unbekannter Fehler').slice(0, 600);
const text = [
  '⚠️ n8n: Workflow fehlgeschlagen',
  'Workflow: ' + (wf.name || '?'),
  'Knoten: ' + (ex.lastNodeExecuted || '?'),
  'Fehler: ' + msg,
  'Lauf-ID: ' + (ex.id || '?') + (ex.mode ? ' (' + ex.mode + ')' : ''),
  ex.url ? 'Öffnen: ' + ex.url : null,
].filter(Boolean).join('\n');
return [{ json: { text } }];
